data class Slot(val id:String,val start:String,val end:String,val capacity:Int)
data class Ticket(val studentId:String,val slotId:String,val slotLabel:String,val ticket:String,val timestamp:Long)
class Store(private val c:Context){private val p=c.getSharedPreferences("btq",Context.MODE_PRIVATE);private fun defs()=listOf(Slot("S0900","09:00","10:00",30),Slot("S1000","10:00","11:00",30),Slot("S1100","11:00","12:00",30),Slot("S1200","12:00","13:00",30),Slot("S1300","13:00","14:00",30),Slot("S1400","14:00","15:00",30));fun slots():List<Slot>{val r=p.getString("slots",null)?:return defs();return try{val a=JSONArray(r);(0 until a.length()).map{val o=a.getJSONObject(it);Slot(o.getString("id"),o.getString("start"),o.getString("end"),o.getInt("capacity"))}}catch(e:Exception){defs()}};fun saveSlots(v:List<Slot>){val a=JSONArray();v.forEach{a.put(JSONObject().put("id",it.id).put("start",it.start).put("end",it.end).put("capacity",it.capacity))};p.edit().putString("slots",a.toString()).apply()};fun tickets():List<Ticket>{val a=JSONArray(p.getString("tickets","[]"));return(0 until a.length()).map{val o=a.getJSONObject(it);Ticket(o.getString("studentId"),o.getString("slotId"),o.getString("slotLabel"),o.getString("ticket"),o.getLong("timestamp"))}};fun save(t:Ticket){val a=JSONArray(p.getString("tickets","[]"));a.put(JSONObject().put("studentId",t.studentId).put("slotId",t.slotId).put("slotLabel",t.slotLabel).put("ticket",t.ticket).put("timestamp",t.timestamp));p.edit().putString("tickets",a.toString()).apply()};fun reset(){p.edit().clear().apply()}}
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Color(0xFF75412D))){App()}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun App(){val c=LocalContext.current;val st=remember{Store(c)};var slots by remember{mutableStateOf(st.slots())};var tickets by remember{mutableStateOf(st.tickets())};var page by remember{mutableStateOf("home")};var chosen by remember{mutableStateOf<Slot?>(null)};var sid by remember{mutableStateOf("")};var issued by remember{mutableStateOf<Ticket?>(null)};var msg by remember{mutableStateOf("")};fun rem(s:Slot)=s.capacity-tickets.count{it.slotId==s.id};Scaffold(topBar={TopAppBar(title={Text("Bubble Tea Queue")},colors=TopAppBarDefaults.topAppBarColors(containerColor=Color(0xFF75412D),titleContentColor=Color.White))}){p->Column(Modifier.padding(p).padding(14.dp).fillMaxSize()){when(page){"home"->{Text("Select collection hour",fontSize=22.sp);LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(slots){s->val r=rem(s);Card(onClick={if(r>0){chosen=s;page="scan"}},enabled=r>0){Row(Modifier.fillMaxWidth().padding(16.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("${s.start} to ${s.end}",fontSize=19.sp);Text("$r of ${s.capacity} remaining")};Text(if(r>0)"AVAILABLE" else "NOT AVAILABLE",color=if(r>0)Color(0xFF17663A)else Color.Red)}}}};Button({page="lookup"},Modifier.fillMaxWidth()){Text("Check Existing Ticket")};OutlinedButton({page="admin"},Modifier.fillMaxWidth()){Text("Kiosk Settings")}};"scan"->{Text("${chosen!!.start} to ${chosen!!.end}",fontSize=22.sp);Scanner{sid=it};OutlinedTextField(sid,{sid=it},label={Text("Student ID")},modifier=Modifier.fillMaxWidth());if(msg.isNotEmpty())Text(msg,color=Color.Red);Button({val x=sid.trim();val old=tickets.find{it.studentId.equals(x,true)};val s=chosen!!;when{x.isBlank()->msg="Scan or enter Student ID.";old!=null->msg="Already issued: ${old.ticket}, ${old.slotLabel}.";rem(s)<=0->{msg="NOT AVAILABLE";page="home"};else->{val n=tickets.count{it.slotId==s.id}+1;val t=Ticket(x,s.id,"${s.start} to ${s.end}","${s.start.substring(0,2)}-${n.toString().padStart(3,'0')}",System.currentTimeMillis());st.save(t);tickets=st.tickets();issued=t;page="ticket"}}},Modifier.fillMaxWidth()){Text("Issue Queue Ticket")};OutlinedButton({page="home"},Modifier.fillMaxWidth()){Text("Back")}};"ticket"->{val t=issued!!;Column(Modifier.fillMaxWidth(),horizontalAlignment=Alignment.CenterHorizontally){Text("QUEUE TICKET");Text(t.ticket,fontSize=52.sp,color=Color(0xFF75412D));Text("Collect during");Text(t.slotLabel,fontSize=28.sp);Text(t.studentId);Button({sid="";issued=null;chosen=null;page="home"},Modifier.fillMaxWidth()){Text("Next Student")}}};"lookup"->{var q by remember{mutableStateOf("")};Text("Check Existing Ticket",fontSize=22.sp);OutlinedTextField(q,{q=it},label={Text("Student ID")},modifier=Modifier.fillMaxWidth());val f=tickets.find{it.studentId.equals(q.trim(),true)};if(q.isNotBlank())Text(if(f==null)"No ticket found" else "${f.ticket} | ${f.slotLabel}",fontSize=24.sp);Button({page="home"},Modifier.fillMaxWidth()){Text("Back")}};"admin"->{Text("Hourly capacities",fontSize=22.sp);LazyColumn(Modifier.weight(1f)){items(slots){s->var v by remember(s.id,s.capacity){mutableStateOf(s.capacity.toString())};Row(verticalAlignment=Alignment.CenterVertically){Text("${s.start}-${s.end}",Modifier.weight(1f));OutlinedTextField(v,{z->v=z.filter(Char::isDigit);val cap=v.toIntOrNull()?.coerceIn(0,999)?:0;slots=slots.map{if(it.id==s.id)it.copy(capacity=cap)else it};st.saveSlots(slots)},modifier=Modifier.width(120.dp))}}};Button({st.reset();slots=st.slots();tickets=st.tickets();page="home"},Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Color.Red)){Text("Reset Event Data")};OutlinedButton({page="home"},Modifier.fillMaxWidth()){Text("Back")}}}}}}
@Composable fun Scanner(onScan:(String)->Unit){val c=LocalContext.current;var granted by remember{mutableStateOf(ContextCompat.checkSelfPermission(c,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)};val l=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){granted=it};LaunchedEffect(Unit){if(!granted)l.launch(Manifest.permission.CAMERA)};if(granted)AndroidView(factory={ctx->PreviewView(ctx).also{pv->val f=ProcessCameraProvider.getInstance(ctx);f.addListener({val provider=f.get();val preview=Preview.Builder().build().also{it.surfaceProvider=pv.surfaceProvider};val analysis=ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();val scanner=BarcodeScanning.getClient(BarcodeScannerOptions.Builder().setBarcodeFormats(Barcode.FORMAT_QR_CODE).build());var last="";analysis.setAnalyzer(Executors.newSingleThreadExecutor()){proxy->val m=proxy.image;if(m==null){proxy.close();return@setAnalyzer};scanner.process(InputImage.fromMediaImage(m,proxy.imageInfo.rotationDegrees)).addOnSuccessListener{b->val raw=b.firstOrNull()?.rawValue?.trim();if(!raw.isNullOrBlank()&&raw!=last){last=raw;onScan(raw)}}.addOnCompleteListener{proxy.close()}};provider.unbindAll();provider.bindToLifecycle(ctx as ComponentActivity,CameraSelector.DEFAULT_BACK_CAMERA,preview,analysis)},ContextCompat.getMainExecutor(ctx))}},modifier=Modifier.fillMaxWidth().height(310.dp))else Text("Camera permission is required. Manual Student ID entry remains available.")}
